from jsonb_to_recordset($q$[{"id":7339,"materia":"pen","nivel":0,"enunciado":"Marcos entra numa loja e leva um celular escondido no bolso, sem ninguém ver. Ele comete:","opcoes":["Furto","Roubo","Estelionato","Apropriação indébita"],"explicacao":"Subtração sem violência ou grave ameaça: art. 155 do CP."},{"id":7340,"materia":"pen","nivel":0,"enunciado":"Lucas aponta uma faca para uma mulher e leva a bolsa dela. Ele comete:","opcoes":["Roubo","Furto","Dano","Receptação"],"explicacao":"Subtração com grave ameaça: art. 157 do CP."},{"id":7341,"materia":"pen","nivel":0,"enunciado":"Quem compra um celular sabendo que ele foi roubado comete:","opcoes":["Receptação","Furto","Favorecimento pessoal","Estelionato"],"explicacao":"Art. 180 do CP."},{"id":7342,"materia":"pen","nivel":0,"enunciado":"Paulo engana uma idosa com um falso boleto e recebe o dinheiro dela. Ele comete:","opcoes":["Estelionato","Roubo","Furto","Extorsão"],"explicacao":"Obtém vantagem induzindo a vítima a erro: art. 171 do CP."},{"id":7343,"materia":"pen","nivel":0,"enunciado":"Acusar falsamente alguém de ter cometido um crime é:","opcoes":["Calúnia","Difamação","Injúria","Desacato"],"explicacao":"Calúnia: imputar falsamente fato definido como crime (art. 138)."},{"id":7344,"materia":"pen","nivel":0,"enunciado":"Chamar alguém de “ladrão safado” numa discussão, ofendendo sua dignidade, é em regra:","opcoes":["Injúria","Calúnia","Difamação","Ameaça"],"explicacao":"Injúria ofende a dignidade ou o decoro, sem imputar fato (art. 140)."},{"id":7345,"materia":"pen","nivel":0,"enunciado":"Dizer a alguém “vou te matar” com intenção de intimidá-lo é crime de:","opcoes":["Ameaça","Lesão corporal","Constrangimento ilegal","Vias de fato"],"explicacao":"Art. 147 do CP."},{"id":7346,"materia":"pen","nivel":0,"enunciado":"O funcionário público que se apropria do dinheiro que guarda em razão do cargo comete:","opcoes":["Peculato","Concussão","Corrupção passiva","Prevaricação"],"explicacao":"Art. 312 do CP."},{"id":7347,"materia":"pen","nivel":0,"enunciado":"Quem age para salvar a própria vida de perigo atual que não provocou, sacrificando bem alheio, está em:","opcoes":["Estado de necessidade","Legítima defesa","Exercício regular de direito","Estrito cumprimento do dever legal"],"explicacao":"Art. 24 do CP."},{"id":7348,"materia":"pen","nivel":0,"enunciado":"Quem repele injusta agressão atual, usando moderadamente os meios necessários, age em:","opcoes":["Legítima defesa","Estado de necessidade","Coação irresistível","Obediência hierárquica"],"explicacao":"Art. 25 do CP."},{"id":7349,"materia":"pen","nivel":0,"enunciado":"Pelo Código Penal, o crime é tentado quando:","opcoes":["Iniciada a execução, não se consuma por circunstâncias alheias à vontade do agente","O agente apenas planeja o crime","O agente desiste voluntariamente","O crime se consuma, mas sem lucro"],"explicacao":"Art. 14, II, do CP."},{"id":7350,"materia":"pen","nivel":1,"enunciado":"Fabiana ameaça divulgar fotos íntimas de alguém se não receber dinheiro. Ela comete:","opcoes":["Extorsão","Roubo","Estelionato","Ameaça simples"],"explicacao":"Constrange com grave ameaça para obter vantagem econômica: art. 158."},{"id":7351,"materia":"pen","nivel":1,"enunciado":"O funcionário público que exige dinheiro do particular em razão da função comete:","opcoes":["Concussão","Corrupção passiva","Peculato","Prevaricação"],"explicacao":"Exigir: concussão (art. 316). Solicitar ou receber: corrupção passiva."},{"id":7352,"materia":"pen","nivel":1,"enunciado":"Matar a mulher por razões da condição do sexo feminino configura:","opcoes":["Feminicídio, hoje crime autônomo","Homicídio simples","Lesão corporal seguida de morte","Homicídio privilegiado"],"explicacao":"A Lei 14.994/2024 tornou o feminicídio crime autônomo (art. 121-A)."},{"id":7353,"materia":"pen","nivel":1,"enunciado":"Em regra, a imputabilidade penal começa aos:","opcoes":["18 anos","16 anos","21 anos","14 anos"],"explicacao":"Art. 27 do CP e art. 228 da CF."},{"id":7354,"materia":"pen","nivel":2,"enunciado":"O agente que, depois de consumado o furto, devolve espontaneamente o bem antes do recebimento da denúncia, sem violência:","opcoes":["Tem a pena reduzida de 1/3 a 2/3 (arrependimento posterior)","Fica isento de pena","Responde só por tentativa","Tem a punibilidade extinta"],"explicacao":"Art. 16 do CP."},{"id":7355,"materia":"pen","nivel":2,"enunciado":"Quem, após subtrair a coisa, emprega violência para assegurar sua posse comete:","opcoes":["Roubo impróprio","Furto qualificado","Roubo próprio","Extorsão"],"explicacao":"Art. 157, § 1º, do CP."},{"id":7356,"materia":"pen","nivel":2,"enunciado":"O erro sobre elemento constitutivo do tipo legal exclui:","opcoes":["O dolo, permitindo punição por culpa se prevista em lei","Sempre a culpabilidade","A ilicitude","Apenas a pena de multa"],"explicacao":"Erro de tipo: art. 20 do CP."},{"id":7357,"materia":"pen","nivel":2,"enunciado":"O prazo de prescrição é reduzido de metade quando o agente era, ao tempo do crime:","opcoes":["Menor de 21 anos","Maior de 60 anos","Reincidente","Funcionário público"],"explicacao":"Art. 115: menor de 21 na data do fato ou maior de 70 na data da sentença."},{"id":7358,"materia":"pen","nivel":2,"enunciado":"O crime de associação criminosa exige, no mínimo:","opcoes":["3 pessoas","2 pessoas","4 pessoas","5 pessoas"],"explicacao":"Art. 288 do CP."},{"id":7359,"materia":"pen","nivel":3,"enunciado":"No crime continuado simples, aplica-se:","opcoes":["A pena de um só crime, se idênticas, ou a mais grave, aumentada de 1/6 a 2/3","A soma de todas as penas","Apenas a pena mais leve","A pena de um só crime, aumentada até o triplo, sempre"],"explicacao":"Art. 71, caput, do CP."},{"id":7360,"materia":"pen","nivel":3,"enunciado":"Na tentativa, a pena é diminuída de:","opcoes":["1/3 a 2/3","1/6 a 1/2","1/2 a 2/3","1/3 a 1/2"],"explicacao":"Art. 14, parágrafo único, do CP."},{"id":7361,"materia":"pen","nivel":3,"enunciado":"O crime impossível ocorre por:","opcoes":["Ineficácia absoluta do meio ou absoluta impropriedade do objeto","Ineficácia relativa do meio","Arrependimento eficaz","Desistência voluntária"],"explicacao":"Art. 17 do CP. Não se pune nem a tentativa."},{"id":7362,"materia":"pen","nivel":3,"enunciado":"Quanto ao lugar do crime, o Código Penal adota a teoria:","opcoes":["Da ubiquidade","Da atividade","Do resultado","Da territorialidade pura"],"explicacao":"Art. 6º: lugar da ação ou do resultado."},{"id":7363,"materia":"pen","nivel":3,"enunciado":"Furto de veículo automotor que venha a ser transportado para outro estado tem pena de:","opcoes":["Reclusão de 3 a 8 anos","Reclusão de 1 a 4 anos","Reclusão de 2 a 8 anos","Detenção de 1 a 3 anos"],"explicacao":"Art. 155, § 5º, do CP."},{"id":7364,"materia":"pen","nivel":3,"enunciado":"O latrocínio é:","opcoes":["Roubo seguido de morte, crime hediondo de competência do juiz singular","Homicídio julgado pelo Tribunal do Júri","Furto seguido de morte","Roubo com lesão leve"],"explicacao":"Súmula 603 do STF: compete ao juiz singular."},{"id":7365,"materia":"pen","nivel":4,"enunciado":"Quanto à reincidência, não prevalece a condenação anterior se, entre o cumprimento ou extinção da pena e o novo crime, decorreu período superior a:","opcoes":["5 anos","3 anos","8 anos","10 anos"],"explicacao":"Art. 64, I, do CP (período depurador)."},{"id":7366,"materia":"pen","nivel":4,"enunciado":"No concurso material, quando o agente pratica dois ou mais crimes mediante mais de uma ação:","opcoes":["As penas são somadas","Aplica-se a mais grave aumentada de 1/6","Aplica-se só a mais grave","Aplica-se a média das penas"],"explicacao":"Art. 69 do CP."},{"id":7367,"materia":"pen","nivel":4,"enunciado":"A embriaguez completa, voluntária ou culposa, pelo álcool:","opcoes":["Não exclui a imputabilidade penal","Exclui a imputabilidade","Reduz a pena obrigatoriamente","Exclui a ilicitude"],"explicacao":"Art. 28, II, do CP (actio libera in causa)."},{"id":7368,"materia":"pen","nivel":4,"enunciado":"A embriaguez completa proveniente de caso fortuito ou força maior que torna o agente inteiramente incapaz de entender o caráter ilícito do fato:","opcoes":["Isenta de pena","Não altera a pena","É agravante","Só reduz a pena de 1/3"],"explicacao":"Art. 28, § 1º, do CP."},{"id":7369,"materia":"pen","nivel":4,"enunciado":"No arrependimento eficaz, o agente:","opcoes":["Impede que o resultado se produza e responde só pelos atos praticados","Repara o dano após a consumação e tem pena reduzida","Responde pela tentativa","Tem a punibilidade sempre extinta"],"explicacao":"Art. 15 do CP."},{"id":7370,"materia":"pen","nivel":4,"enunciado":"O peculato culposo tem a punibilidade extinta quando:","opcoes":["O dano é reparado antes da sentença irrecorrível","O agente confessa","O dano é reparado após o trânsito em julgado","O agente é primário"],"explicacao":"Art. 312, § 3º. Após a sentença, a reparação reduz a pena pela metade."},{"id":7371,"materia":"pen","nivel":4,"enunciado":"Para o STF, a injúria racial:","opcoes":["É espécie de racismo e, portanto, imprescritível","Prescreve como qualquer crime contra a honra","É apenas contravenção","Só se processa mediante queixa"],"explicacao":"STF (HC 154.248); a Lei 14.532/2023 a levou para a Lei 7.716/1989."},{"id":7372,"materia":"pen","nivel":4,"enunciado":"Na legítima defesa, o excesso doloso ou culposo:","opcoes":["É punível","Exclui sempre a responsabilidade","Transforma o fato em estado de necessidade","Nunca é punível"],"explicacao":"Art. 23, parágrafo único, do CP."},{"id":7373,"materia":"pen","nivel":4,"enunciado":"A extinção da punibilidade pela prescrição da pretensão punitiva antes do trânsito em julgado regula-se:","opcoes":["Pelo máximo da pena privativa de liberdade cominada ao crime","Pela pena mínima","Pela pena aplicada na sentença, sempre","Pelo dobro da pena máxima"],"explicacao":"Art. 109 do CP."},{"id":7374,"materia":"pen","nivel":4,"enunciado":"Quem comete crime sob coação moral irresistível:","opcoes":["Não é punido;